package main

import (
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"unicode"
	"unicode/utf8"
)

const (
	uploadDir   = "/var/uploads"
	servingDir  = "/var/public"
	maxFileSize = 10 << 20 // 10MB
)

// normalizeFilename applies Unicode NFC normalization and strips dangerous chars
func normalizeFilename(name string) string {
	// Remove path separators
	name = filepath.Base(name)
	// Strip null bytes
	name = strings.ReplaceAll(name, "\x00", "")
	// Remove leading dots to prevent hidden files
	name = strings.TrimLeft(name, ".")
	if name == "" {
		name = "unnamed"
	}
	return name
}

// isAllowedExtension checks file extension against whitelist
func isAllowedExtension(filename string) bool {
	allowed := map[string]bool{
		".txt": true, ".pdf": true, ".png": true,
		".jpg": true, ".gif": true, ".doc": true,
	}
	ext := strings.ToLower(filepath.Ext(filename))
	return allowed[ext]
}

// containsHomoglyphs checks for confusable Unicode characters
// that could be used to bypass extension checks
func containsHomoglyphs(s string) bool {
	for _, r := range s {
		if r > 127 && unicode.IsLetter(r) {
			return true
		}
	}
	return false
}

// sanitizeForServing ensures the filename is safe for the public directory
// by checking the entire filename for non-ASCII characters
func sanitizeForServing(filename string) (string, error) {
	if !utf8.ValidString(filename) {
		return "", fmt.Errorf("invalid UTF-8 in filename")
	}
	// Check the ENTIRE filename (including extension) for homoglyphs
	if containsHomoglyphs(filename) {
		return "", fmt.Errorf("filename contains non-ASCII characters")
	}
	return filename, nil
}

// hashContent generates a content-based hash prefix
func hashContent(data []byte) string {
	h := sha256.Sum256(data)
	return hex.EncodeToString(h[:8])
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Verify request comes from trusted reverse proxy
	proxyToken := r.Header.Get("X-Internal-Auth")
	expected := os.Getenv("PROXY_SECRET")
	if expected == "" || subtle.ConstantTimeCompare([]byte(proxyToken), []byte(expected)) != 1 {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxFileSize)
	file, header, err := r.FormFile("document")
	if err != nil {
		http.Error(w, "Bad request", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// Step 1: Normalize the filename
	originalName := normalizeFilename(header.Filename)

	// Step 2: Sanitize BEFORE extension check to prevent homoglyph bypass
	_, err = sanitizeForServing(originalName)
	if err != nil {
		http.Error(w, "Invalid filename: "+err.Error(), http.StatusBadRequest)
		return
	}

	// Step 3: Check extension whitelist (now safe from homoglyph confusion)
	if !isAllowedExtension(originalName) {
		http.Error(w, "File type not allowed", http.StatusForbidden)
		return
	}

	// Step 4: Read file content
	content, err := io.ReadAll(file)
	if err != nil {
		http.Error(w, "Read error", http.StatusInternalServerError)
		return
	}

	// Step 5: Generate safe storage name
	hash := hashContent(content)
	storeName := hash + "_" + originalName

	// Step 6: Write to upload directory (no symlinks, direct copy)
	dstPath := filepath.Join(uploadDir, storeName)
	if err := os.WriteFile(dstPath, content, 0644); err != nil {
		http.Error(w, "Storage error", http.StatusInternalServerError)
		return
	}

	// Step 7: Copy file to public serving directory (no symlinks)
	publicPath := filepath.Join(servingDir, originalName)
	if err := os.WriteFile(publicPath, content, 0444); err != nil {
		http.Error(w, "Publish error", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, "File uploaded: %s\n", originalName)
}

func serveHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	reqPath := strings.TrimPrefix(r.URL.Path, "/files/")
	if reqPath == "" || strings.Contains(reqPath, "/") || strings.Contains(reqPath, "..") {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}

	// Verify the resolved path is within servingDir
	fullPath := filepath.Join(servingDir, reqPath)
	resolved, err := filepath.EvalSymlinks(fullPath)
	if err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}
	// Enforce a strict directory boundary to avoid sibling-prefix bypass
	// (e.g. "/var/public-evil" should not match "/var/public").
	if resolved != servingDir && !strings.HasPrefix(resolved, servingDir+string(os.PathSeparator)) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	http.ServeFile(w, r, resolved)
}

func main() {
	os.MkdirAll(uploadDir, 0755)
	os.MkdirAll(servingDir, 0755)

	mux := http.NewServeMux()
	mux.HandleFunc("/upload", uploadHandler)
	mux.HandleFunc("/files/", serveHandler)

	server := &http.Server{
		Addr:    ":8080",
		Handler: mux,
	}

	fmt.Println("File service listening on :8080")
	server.ListenAndServe()
}
